/* © 2026 Mtro. Carlos Gabriel Ortega Gutiérrez · Tlamatini Aula.
   Banco de reactivos para la actualización diaria rumbo a los procesos de USICAMM (promoción horizontal, promoción a dirección
   o supervisión, horas adicionales, asesoría técnica pedagógica). Estructura y formatos tomados de las guías oficiales 2026-2027:
   instrumento de apreciación de conocimientos y aptitudes, opción múltiple con 3 opciones; formatos: cuestionamiento directo,
   completamiento, ordenamiento y relación de elementos. Áreas: aspectos normativos, intervención docente / marco curricular,
   inclusión y convivencia, gestión y mejora continua, escuela-familia-comunidad, desarrollo y aprendizaje.
   Cada reactivo: a = área, f = formato, p = planteamiento, o = 3 opciones, k = índice correcto, e = explicación, fu = fundamento,
   per = perfiles a los que aplica (vacío = todos: doc docente, dir dirección, sup supervisión, atp asesoría). */
"use strict";
const EST_AREAS = { norm: "Aspectos normativos", curr: "Plan de Estudio 2022 y práctica docente", incl: "Inclusión, convivencia y protección", gest: "Gestión escolar y mejora continua", com: "Escuela, familias y comunidad", apr: "Desarrollo y aprendizaje" };
const EST_FORMATOS = { d: "Cuestionamiento directo", c: "Completamiento", or: "Ordenamiento", r: "Relación de elementos" };
const EST_BANCO = [
/* ===================== ASPECTOS NORMATIVOS: ARTÍCULO 3o, 4o Y 31 CONSTITUCIONAL ===================== */
{ id: "n01", a: "norm", f: "c", p: "Según el artículo 3o constitucional, la educación que imparte el Estado, además de obligatoria, debe ser universal, inclusiva, pública, gratuita y ________.", o: ["laica", "bilingüe", "técnica"], k: 0,
  e: "El segundo párrafo del artículo 3o señala que corresponde al Estado la rectoría de la educación y que la que imparte es obligatoria, universal, inclusiva, pública, gratuita y laica. La fracción I precisa que, por ser laica, se mantiene ajena a cualquier doctrina religiosa.", fu: "Constitución Política de los Estados Unidos Mexicanos, art. 3o, párrafo segundo y fracción I." },
{ id: "n02", a: "norm", f: "d", p: "Una madre pregunta por qué la escuela dio prioridad a la permanencia de su hijo, que trabaja por las tardes, en lugar de darlo de baja por inasistencias. ¿Qué principio del artículo 3o sustenta la decisión?", o: ["El interés superior de niñas, niños, adolescentes y jóvenes en el acceso, la permanencia y la participación en los servicios educativos", "La autonomía de gestión de la escuela para fijar sus propias reglas de inscripción", "La facultad del director para condicionar la permanencia al cumplimiento de la asistencia"], k: 0,
  e: "El artículo 3o establece que en la prestación de los servicios educativos se priorizará el interés superior de niñas, niños, adolescentes y jóvenes en el acceso, la permanencia y la participación. Dar de baja sin agotar apoyos contradice ese principio.", fu: "CPEUM, art. 3o, párrafo quinto; art. 4o (interés superior de la niñez)." },
{ id: "n03", a: "norm", f: "d", p: "¿Cómo reconoce el artículo 3o constitucional a las maestras y los maestros?", o: ["Como agentes fundamentales del proceso educativo y, por tanto, de la transformación social", "Como responsables únicos del aprendizaje de los educandos", "Como trabajadores administrativos al servicio de la autoridad educativa"], k: 0,
  e: "El artículo 3o reconoce a maestras y maestros como agentes fundamentales del proceso educativo, con derecho a acceder a un sistema integral de formación, capacitación y actualización, retroalimentado por evaluaciones diagnósticas.", fu: "CPEUM, art. 3o, párrafo sexto." },
{ id: "n04", a: "norm", f: "r", p: "Relacione cada criterio de la educación (fracción II del art. 3o) con su descripción.\n1. Equitativo\n2. Inclusivo\n3. Intercultural\na) Promueve la convivencia armónica y el respeto a las diferencias\nb) Combate las desigualdades socioeconómicas, regionales y de género\nc) Toma en cuenta las diversas capacidades, circunstancias y necesidades, con ajustes razonables", o: ["1b, 2c, 3a", "1c, 2a, 3b", "1a, 2b, 3c"], k: 0,
  e: "Equitativo combate las desigualdades (inciso e); inclusivo atiende las diversas capacidades y necesidades de los educandos con ajustes razonables (inciso f); intercultural promueve la convivencia y el respeto a las diferencias (inciso g).", fu: "CPEUM, art. 3o, fracción II, incisos e), f) y g)." },
{ id: "n05", a: "norm", f: "c", p: "La fracción II del artículo 3o define el criterio de ________ como el que busca el máximo logro de aprendizaje de los educandos, el desarrollo de su pensamiento crítico y el fortalecimiento de los lazos entre escuela y comunidad.", o: ["excelencia", "calidad", "eficiencia"], k: 0,
  e: "Desde la reforma de 2019 el criterio ya no se llama «calidad», sino «excelencia», entendida como el mejoramiento integral constante que promueve el máximo logro de aprendizaje, el pensamiento crítico y el vínculo escuela-comunidad.", fu: "CPEUM, art. 3o, fracción II, inciso i)." },
{ id: "n06", a: "norm", f: "d", p: "De acuerdo con el artículo 3o, ¿cómo deben realizarse la admisión, la promoción y el reconocimiento del personal docente, directivo y de supervisión?", o: ["Mediante procesos de selección públicos, transparentes, equitativos e imparciales", "Mediante la propuesta de la autoridad inmediata superior", "Mediante una evaluación de permanencia obligatoria cada cuatro años"], k: 0,
  e: "El artículo 3o dispone que la admisión, promoción y reconocimiento se realicen por procesos públicos, transparentes, equitativos e imparciales, y que no afecten la permanencia de quienes ya están en servicio. Los regula la Ley General del Sistema para la Carrera de las Maestras y los Maestros.", fu: "CPEUM, art. 3o, párrafos séptimo y octavo." },
{ id: "n07", a: "norm", f: "d", p: "¿Qué orientación deben tener los planes y programas de estudio según el artículo 3o constitucional?", o: ["Perspectiva de género y orientación integral", "Enfoque por competencias para el mercado laboral", "Contenidos idénticos para todo el país, sin contextualizar"], k: 0,
  e: "El artículo 3o señala que los planes y programas tendrán perspectiva de género y una orientación integral, e incluirán, entre otros, conocimientos de ciencias y humanidades, lenguas indígenas, artes, educación física, educación sexual y reproductiva y cuidado al medio ambiente.", fu: "CPEUM, art. 3o, párrafo duodécimo." },
{ id: "n08", a: "norm", f: "d", p: "El artículo 4o constitucional ordena que en todas las decisiones y actuaciones del Estado se vele y cumpla un principio respecto de niñas y niños. ¿Cuál?", o: ["El interés superior de la niñez", "La patria potestad", "La tutela administrativa"], k: 0,
  e: "El artículo 4o establece que en todas las decisiones y actuaciones del Estado se velará y cumplirá con el principio del interés superior de la niñez, garantizando de manera plena sus derechos; este principio guía el diseño, ejecución y evaluación de las políticas públicas.", fu: "CPEUM, art. 4o, párrafo noveno." },
{ id: "n09", a: "norm", f: "d", p: "En la escuela se propone que el grupo rece antes de iniciar las actividades. ¿Qué responde la directora con base en la Constitución?", o: ["Que la educación que imparte el Estado es laica y se mantiene ajena a cualquier doctrina religiosa, respetando la libertad de creencias de todos", "Que puede hacerse si la mayoría de las familias está de acuerdo", "Que solo puede hacerse fuera del horario de clases dentro del aula"], k: 0,
  e: "La fracción I del artículo 3o establece que, garantizada por el artículo 24 la libertad de creencias, la educación será laica y, por tanto, se mantendrá por completo ajena a cualquier doctrina religiosa.", fu: "CPEUM, art. 3o, fracción I; art. 24." },
{ id: "n10", a: "norm", f: "d", p: "Según el artículo 3o, ¿qué tipo de educación queda establecida como obligatoria?", o: ["La educación básica (preescolar, primaria y secundaria) y la media superior; la superior en los términos de la fracción X", "Solo la primaria y la secundaria", "La primaria, la secundaria y la superior"], k: 0,
  e: "El primer párrafo del artículo 3o establece que la educación inicial, preescolar, primaria, secundaria, media superior y superior las imparte y garantiza el Estado; la básica y la media superior son obligatorias, y la superior lo es en términos de la fracción X.", fu: "CPEUM, art. 3o, párrafo primero y fracción X." },

/* ===================== LEY GENERAL DE EDUCACIÓN ===================== */
{ id: "n11", a: "norm", f: "d", p: "Una escuela pide la cuota voluntaria como requisito para entregar la boleta. ¿Qué establece la Ley General de Educación?", o: ["Que no pueden condicionarse la inscripción, el acceso, la entrega de documentos ni la prestación del servicio al pago de contraprestaciones; las aportaciones voluntarias no son pago", "Que puede hacerse si lo acordó la asociación de madres y padres de familia", "Que es válido siempre que la cuota se use en mantenimiento"], k: 0,
  e: "El artículo 7, fracción IV, establece que la educación pública es gratuita: se prohíbe el pago de cualquier contraprestación que impida o condicione la prestación del servicio, como la inscripción o la entrega de documentación. Las donaciones o cuotas voluntarias no se consideran contraprestación.", fu: "Ley General de Educación (LGE), art. 7, fracción IV." },
{ id: "n12", a: "norm", f: "c", p: "La Ley General de Educación señala que la educación será inclusiva al eliminar toda forma de discriminación y exclusión, así como las ________ para el aprendizaje y la participación.", o: ["barreras", "dificultades", "necesidades educativas especiales"], k: 0,
  e: "La LGE adopta el enfoque de barreras para el aprendizaje y la participación (BAP): no se centra en la «deficiencia» del alumno, sino en lo que el contexto, las prácticas y las actitudes deben cambiar. Lo menciona tanto en las características (art. 7) como en el criterio inclusivo (art. 16, fracción VII).", fu: "LGE, art. 7, fracción II; art. 16, fracción VII." },
{ id: "n13", a: "norm", f: "d", p: "¿Qué propósito central plantea la Ley General de Educación para la Nueva Escuela Mexicana?", o: ["Buscar la equidad, la excelencia y la mejora continua, colocando al centro el máximo logro de aprendizaje de niñas, niños, adolescentes y jóvenes", "Elevar los resultados en pruebas estandarizadas internacionales", "Uniformar la enseñanza en todas las escuelas del país"], k: 0,
  e: "El artículo 11 de la LGE establece que la Nueva Escuela Mexicana busca la equidad, la excelencia y la mejora continua en la educación, colocando al centro de la acción pública el máximo logro de aprendizaje, con el desarrollo humano integral como uno de sus objetivos.", fu: "LGE, art. 11." },
{ id: "n14", a: "norm", f: "r", p: "Relacione cada criterio de la educación de la LGE (art. 16) con su sentido.\n1. Humanista\n2. Integral\n3. De excelencia\na) Desarrolla habilidades cognitivas, socioemocionales y físicas\nb) Se orienta al mejoramiento permanente de los procesos formativos\nc) Favorece el respeto a la dignidad humana y la igualdad de derechos", o: ["1c, 2a, 3b", "1a, 2b, 3c", "1b, 2c, 3a"], k: 0,
  e: "En el artículo 16 de la LGE, el criterio humanista se refiere a la dignidad y la igualdad de derechos; el integral, a educar para la vida desarrollando capacidades cognitivas, socioemocionales y físicas; y el de excelencia, a la mejora permanente de los procesos formativos.", fu: "LGE, art. 16, fracciones III, IX y X." },
{ id: "n15", a: "norm", f: "d", p: "Entre los fines de la educación que señala la LGE, ¿cuál se relaciona directamente con la resolución de conflictos en el aula?", o: ["Inculcar el respeto, la cultura de paz y la solución no violenta de conflictos", "Fomentar la competencia entre estudiantes", "Garantizar la disciplina mediante sanciones"], k: 0,
  e: "El artículo 15 de la LGE enumera los fines de la educación; uno de ellos es promover el respeto, la cultura de paz y la no violencia, incluida la solución pacífica de conflictos. Por eso las intervenciones ante un conflicto deben ser formativas y dialógicas.", fu: "LGE, art. 15, fracción V." },
{ id: "n16", a: "norm", f: "d", p: "¿Qué dice la Ley General de Educación sobre la corresponsabilidad de madres, padres o tutores?", o: ["Que son corresponsables del proceso educativo: deben hacer que asistan a la escuela, apoyar su aprendizaje y revisar su progreso, desempeño y conducta", "Que su participación es opcional y solo administrativa", "Que deciden los contenidos que se enseñan en el grupo"], k: 0,
  e: "El artículo 78 de la LGE establece que madres, padres o tutores son corresponsables del proceso educativo de sus hijas e hijos menores de 18 años. Además, obliga a las autoridades a orientar a las familias en temas como crianza, salud, disciplina positiva y prevención de la violencia.", fu: "LGE, art. 78." },
{ id: "n17", a: "norm", f: "d", p: "La asociación de madres y padres quiere decidir qué metodología usará la maestra de 4.° grado. ¿Qué establece la LGE?", o: ["Que las asociaciones deben abstenerse de intervenir en los aspectos pedagógicos y laborales de los establecimientos educativos", "Que pueden decidirlo si lo aprueba la mayoría en asamblea", "Que pueden hacerlo solo en escuelas de organización completa"], k: 0,
  e: "El artículo 130 de la LGE señala el objeto de las asociaciones de madres y padres de familia (representar intereses comunes, colaborar en la mejora de los planteles, entre otros) y precisa que se abstendrán de intervenir en los aspectos pedagógicos y laborales.", fu: "LGE, art. 130." },
{ id: "n18", a: "norm", f: "d", p: "¿A partir de qué grado pueden participar los estudiantes en los Comités Escolares de Administración Participativa, según la LGE?", o: ["Desde cuarto grado de primaria", "Desde primer grado de secundaria", "Solo en educación media superior"], k: 0,
  e: "El artículo 106 de la LGE regula los Comités Escolares de Administración Participativa, que reciben presupuesto anual para mejoras y mantenimiento. Se eligen al inicio del ciclo en asamblea escolar con docentes, directivos, madres y padres, y estudiantes a partir del cuarto grado de primaria.", fu: "LGE, art. 106.", per: ["dir", "sup", "atp"] },
{ id: "n19", a: "norm", f: "d", p: "Según la LGE, ¿quién decide si en una escuela pública de educación básica se instala un consejo de participación escolar?", o: ["La propia escuela, que lo integra con las asociaciones de madres y padres y con el personal docente", "La Secretaría de Educación Pública, de manera obligatoria en todas las escuelas", "El ayuntamiento, a propuesta del supervisor"], k: 0,
  e: "El artículo 132 de la LGE establece que la autoridad de cada escuela pública la vinculará con la comunidad, y que la escuela podrá instalar un consejo de participación escolar o su equivalente, integrado por las asociaciones de madres y padres y docentes, que puede, entre otras cosas, impulsar la alimentación saludable y apoyar la protección civil.", fu: "LGE, art. 132.", per: ["dir", "sup", "atp"] },
{ id: "n20", a: "norm", f: "d", p: "¿Qué obligación de madres, padres o tutores prevé la LGE cuando se presentan cambios en la conducta de sus hijos?", o: ["Informar a las autoridades educativas sobre cualquier problema relacionado con la educación de sus hijos, incluidos cambios de conducta", "Solicitar el cambio de grupo de inmediato", "Llevarlo a terapia privada como requisito para su permanencia"], k: 0,
  e: "El artículo 129 de la LGE enumera las obligaciones de quienes ejercen la patria potestad o tutela; entre ellas, informar a las autoridades sobre cambios de conducta y de actitud de los educandos, para que se apliquen los estudios correspondientes, y acudir a los llamados de la escuela.", fu: "LGE, art. 129." },
{ id: "n21", a: "norm", f: "c", p: "La LGE señala que la educación inicial es un derecho de la niñez y que es ________ del Estado concientizar sobre su importancia.", o: ["responsabilidad", "opción", "atribución de las familias"], k: 0,
  e: "El artículo 6 de la LGE establece la obligatoriedad de la educación preescolar, primaria, secundaria y media superior, y precisa que la educación inicial es un derecho de la niñez y una responsabilidad del Estado concientizar sobre su importancia.", fu: "LGE, art. 6." },
{ id: "n22", a: "norm", f: "r", p: "Relacione cada característica de la educación (art. 7 LGE) con su contenido.\n1. Universal\n2. Pública\n3. Gratuita\na) Prohíbe condicionar la inscripción o la entrega de documentos a un pago\nb) Se extiende a todas las personas, sin discriminación\nc) Es impartida y administrada por el Estado, que vigila la de los particulares", o: ["1b, 2c, 3a", "1a, 2b, 3c", "1c, 2a, 3b"], k: 0,
  e: "Según el artículo 7 de la LGE, universal significa que se extiende a todas las personas sin discriminación; pública, que la imparte y administra el Estado de manera directa (y vigila la que imparten particulares); y gratuita, que prohíbe condicionar el servicio a contraprestaciones.", fu: "LGE, art. 7, fracciones I, III y IV." },

/* ===================== DERECHOS DE NIÑAS, NIÑOS Y ADOLESCENTES ===================== */
{ id: "n23", a: "norm", f: "d", p: "La maestra quiere publicar en redes sociales fotografías de un alumno durante un conflicto para «concientizar» a las familias. ¿Qué derecho se vulneraría?", o: ["El derecho a la intimidad, que prohíbe difundir datos o imágenes que menoscaben su honra o reputación", "El derecho a la libertad de expresión de la docente", "Ninguno, si la imagen es de un evento escolar"], k: 0,
  e: "La Ley General de los Derechos de Niñas, Niños y Adolescentes reconoce el derecho a la intimidad personal y prohíbe difundir información o imágenes que permitan identificarlos y que atenten contra su honra, imagen o reputación. Para publicar imágenes de eventos se requiere autorización de quien ejerce la patria potestad.", fu: "LGDNNA, arts. 76 y 77." },
{ id: "n24", a: "norm", f: "d", p: "Un alumno de 5.° pide ser escuchado antes de que se decida un cambio de grupo que le afecta. ¿Qué derecho le reconoce la Ley General de los Derechos de Niñas, Niños y Adolescentes?", o: ["El derecho a expresar su opinión y a que sea tomada en cuenta en los asuntos que le afectan, según su edad y madurez", "Ninguno: la decisión corresponde solo a los adultos", "El derecho a decidir por sí mismo su grupo"], k: 0,
  e: "La LGDNNA reconoce el derecho de niñas, niños y adolescentes a ser escuchados y tomados en cuenta en los asuntos de su interés, conforme a su edad, desarrollo cognoscitivo y madurez (derecho a la participación).", fu: "LGDNNA, arts. 71 y 72." },
{ id: "n25", a: "norm", f: "d", p: "¿Qué artículo de la Ley General de los Derechos de Niñas, Niños y Adolescentes reconoce su derecho a una educación de calidad que contribuya al conocimiento de sus derechos?", o: ["Artículo 57", "Artículo 103", "Artículo 1"], k: 0,
  e: "El artículo 57 de la LGDNNA reconoce el derecho a una educación que contribuya al conocimiento de sus propios derechos, basada en un enfoque de derechos humanos e igualdad sustantiva, y enumera obligaciones de las autoridades para garantizarlo (acceso, permanencia, inclusión, convivencia sin violencia, entre otras).", fu: "LGDNNA, art. 57." },
{ id: "n26", a: "norm", f: "c", p: "La LGDNNA establece que niñas, niños y adolescentes tienen derecho a vivir una vida libre de toda forma de ________ y a que se resguarde su integridad personal.", o: ["violencia", "responsabilidad", "supervisión"], k: 0,
  e: "El artículo 46 de la LGDNNA reconoce el derecho a una vida libre de toda forma de violencia y a que se resguarde su integridad personal, a fin de lograr las mejores condiciones de bienestar y el libre desarrollo de su personalidad.", fu: "LGDNNA, art. 46." },
{ id: "n27", a: "norm", f: "d", p: "Ante una sospecha fundada de maltrato en casa de un alumno, ¿qué debe hacer la escuela?", o: ["Dar aviso de inmediato a la autoridad competente (Procuraduría de Protección o Ministerio Público) siguiendo el protocolo, sin investigar por cuenta propia ni confrontar a la familia", "Esperar a reunir pruebas suficientes antes de informar", "Citar a la familia para que expliquen las marcas frente al alumno"], k: 0,
  e: "La LGDNNA obliga a quienes conozcan de casos de violencia contra niñas, niños y adolescentes a hacerlo del conocimiento de la autoridad competente. La escuela no investiga ni confronta: protege, documenta lo observado, da aviso y sigue su protocolo, cuidando la confidencialidad.", fu: "LGDNNA, arts. 46 y 47; Acuerdo 17/05/25 y protocolos de actuación de la entidad." },

/* ===================== PLAN DE ESTUDIO 2022 ===================== */
{ id: "c01", a: "curr", f: "d", p: "¿Cuáles son los cuatro campos formativos del Plan de Estudio 2022?", o: ["Lenguajes; Saberes y pensamiento científico; Ética, naturaleza y sociedades; De lo humano y lo comunitario", "Lenguaje y comunicación; Pensamiento matemático; Exploración del mundo; Desarrollo personal y social", "Español; Matemáticas; Ciencias; Formación cívica y ética"], k: 0,
  e: "El Plan de Estudio 2022 organiza los contenidos en cuatro campos formativos que integran saberes de distintas disciplinas: Lenguajes; Saberes y pensamiento científico; Ética, naturaleza y sociedades; y De lo humano y lo comunitario. La segunda opción corresponde a planes anteriores.", fu: "SEP, Plan de Estudio para la educación preescolar, primaria y secundaria 2022 (Acuerdo 14/08/22)." },
{ id: "c02", a: "curr", f: "d", p: "¿Cuántos ejes articuladores establece el Plan de Estudio 2022?", o: ["Siete", "Cuatro", "Seis"], k: 0,
  e: "Son siete ejes articuladores: inclusión; pensamiento crítico; interculturalidad crítica; igualdad de género; vida saludable; apropiación de las culturas a través de la lectura y la escritura; y artes y experiencias estéticas. Vinculan los contenidos con la realidad de los estudiantes.", fu: "SEP, Plan de Estudio 2022." },
{ id: "c03", a: "curr", f: "r", p: "Relacione cada fase del Plan de Estudio 2022 con los grados que comprende.\n1. Fase 3\n2. Fase 5\n3. Fase 6\na) 1.°, 2.° y 3.° de secundaria\nb) 1.° y 2.° de primaria\nc) 5.° y 6.° de primaria", o: ["1b, 2c, 3a", "1c, 2b, 3a", "1a, 2c, 3b"], k: 0,
  e: "El Plan 2022 organiza la educación básica en seis fases: Fase 1 educación inicial; Fase 2 preescolar; Fase 3 primero y segundo de primaria; Fase 4 tercero y cuarto; Fase 5 quinto y sexto; Fase 6 secundaria.", fu: "SEP, Plan de Estudio 2022; Programas Sintéticos de las Fases 2 a 6." },
{ id: "c04", a: "curr", f: "c", p: "En el Plan de Estudio 2022, la ________ es el espacio social, cultural, político, productivo y simbólico en el que se inscribe la escuela, y se considera el núcleo integrador de los procesos de enseñanza y aprendizaje.", o: ["comunidad", "familia", "zona escolar"], k: 0,
  e: "Uno de los elementos centrales del Plan 2022 es la comunidad como núcleo integrador: los contenidos se vinculan con la vida cotidiana y los problemas del entorno de los estudiantes, y la escuela se abre a la comunidad.", fu: "SEP, Plan de Estudio 2022, «La comunidad como núcleo integrador»." },
{ id: "c05", a: "curr", f: "d", p: "¿Qué diferencia hay entre el programa sintético y el programa analítico?", o: ["El sintético es nacional y contiene contenidos y PDA por fase; el analítico lo elabora el colectivo de cada escuela, contextualizando el sintético a su realidad (codiseño)", "El sintético lo elabora cada docente y el analítico lo publica la SEP", "Son el mismo documento con distinto nombre"], k: 0,
  e: "El programa sintético es el primer nivel de concreción, de carácter nacional, con contenidos y procesos de desarrollo de aprendizaje. El programa analítico es la concreción en cada escuela: el colectivo docente lo construye a partir de la lectura de la realidad y puede incorporar contenidos propios mediante el codiseño.", fu: "SEP, Programas Sintéticos de las Fases 2 a 6 (Acuerdo 08/08/23), apartado «El Programa Analítico»." },
{ id: "c06", a: "curr", f: "or", p: "Ordene los planos para la construcción del programa analítico.\n1. Contextualización de los contenidos del programa sintético\n2. Lectura de la realidad (diagnóstico socioeducativo)\n3. Formulación del programa analítico", o: ["2, 1, 3", "1, 2, 3", "3, 2, 1"], k: 0,
  e: "El programa analítico se construye en tres planos: primero la lectura de la realidad (análisis del contexto socioeducativo de la escuela), después la contextualización de los contenidos del programa sintético y, por último, su formulación.", fu: "SEP, Programas Sintéticos de las Fases 2 a 6, «El Programa Analítico: primer, segundo y tercer plano»." },
{ id: "c07", a: "curr", f: "c", p: "En el seguimiento al programa analítico, el codiseño debe entenderse como un ejercicio de ________ curricular colectiva, y no como un listado de actividades de clase.", o: ["deliberación", "supervisión", "evaluación"], k: 0,
  e: "Este es justamente el ejemplo de completamiento de la guía oficial: el codiseño es un proceso de deliberación curricular del colectivo docente, que decide cómo contextualizar los contenidos nacionales y cuáles contenidos locales incorporar.", fu: "USICAMM, Guía de apoyo 2026-2027, formatos de reactivos; Plan de Estudio 2022 (codiseño)." },
{ id: "c08", a: "curr", f: "r", p: "Relacione cada rasgo del Plan de Estudio 2022 con lo que implica.\n1. Integración curricular\n2. Autonomía profesional del magisterio\n3. Comunidad como núcleo integrador\na) Vincular los procesos de enseñanza con la vida y los problemas del entorno\nb) Que el docente decida, con su colectivo, cómo contextualizar y enseñar los contenidos\nc) Articular saberes de distintas disciplinas en campos formativos", o: ["1c, 2b, 3a", "1a, 2c, 3b", "1b, 2a, 3c"], k: 0,
  e: "Es el ejemplo de relación de elementos de la guía oficial (respuesta 1c, 2b, 3a). La integración curricular organiza los saberes en campos; la autonomía profesional reconoce la capacidad del docente para decidir; la comunidad es el núcleo integrador.", fu: "USICAMM, Guía de apoyo 2026-2027; SEP, Plan de Estudio 2022." },
{ id: "c09", a: "curr", f: "d", p: "¿Qué son los Procesos de Desarrollo de Aprendizaje (PDA)?", o: ["Las descripciones, por grado, de cómo se espera que avance el aprendizaje de cada contenido del programa sintético", "Los exámenes trimestrales que se aplican a cada grupo", "Las actividades que el docente realiza en cada sesión"], k: 0,
  e: "En los programas sintéticos, cada contenido se acompaña de Procesos de Desarrollo de Aprendizaje que describen, por grado dentro de la fase, la progresión esperada. Orientan la planeación y la evaluación formativa; no son actividades ni exámenes.", fu: "SEP, Programas Sintéticos de las Fases 2 a 6." },
{ id: "c10", a: "curr", f: "r", p: "Relacione cada campo formativo con la metodología sociocrítica que los programas sugieren con mayor frecuencia.\n1. Lenguajes\n2. Saberes y pensamiento científico\n3. Ética, naturaleza y sociedades\na) Aprendizaje basado en problemas\nb) Proyectos comunitarios\nc) Indagación con enfoque STEAM", o: ["1b, 2c, 3a", "1a, 2b, 3c", "1c, 2a, 3b"], k: 0,
  e: "Las orientaciones y los libros de texto asocian: Lenguajes con proyectos comunitarios; Saberes y pensamiento científico con indagación (STEAM); Ética, naturaleza y sociedades con aprendizaje basado en problemas; y De lo humano y lo comunitario con aprendizaje servicio. Son sugerencias, no obligaciones: el docente decide con autonomía.", fu: "SEP, Un libro sin recetas para la maestra y el maestro; Plan de Estudio 2022 (metodologías)." },
{ id: "c11", a: "curr", f: "d", p: "¿Cuáles son los tres escenarios en los que se organizan los proyectos de los libros de texto de la Nueva Escuela Mexicana?", o: ["Aula, escolar y comunitario", "Individual, de equipo y grupal", "Presencial, a distancia e híbrido"], k: 0,
  e: "Los libros de proyectos de primaria se organizan por escenarios (Proyectos de Aula, Proyectos Escolares y Proyectos Comunitarios), según el alcance del proyecto: dentro del grupo, con la escuela o con la comunidad.", fu: "SEP, Libros de Texto Gratuitos 2023 en adelante; Plan de Estudio 2022." },
{ id: "c12", a: "curr", f: "d", p: "¿Cuál es el propósito principal de la evaluación formativa en el Plan de Estudio 2022?", o: ["Acompañar y retroalimentar el proceso de aprendizaje para ajustar la enseñanza, no solo asignar una calificación", "Clasificar a los alumnos según su rendimiento", "Obtener el promedio del grupo para el reporte trimestral"], k: 0,
  e: "El Plan 2022 privilegia la evaluación formativa: se realiza durante el proceso, recupera evidencias, retroalimenta a estudiantes y orienta las decisiones del docente. La calificación es un elemento de la evaluación sumativa, que no sustituye lo formativo.", fu: "SEP, Plan de Estudio 2022 (evaluación formativa); La evaluación formativa es un reto pedagógico-didáctico en el trabajo docente (2024)." },
{ id: "c13", a: "curr", f: "c", p: "El eje articulador «________» busca que los estudiantes cuestionen la realidad, argumenten y tomen postura ante situaciones de su entorno.", o: ["Pensamiento crítico", "Vida saludable", "Artes y experiencias estéticas"], k: 0,
  e: "El pensamiento crítico es uno de los siete ejes articuladores; promueve la capacidad de interrogar la realidad, analizar, argumentar y transformar. Los ejes atraviesan todos los campos formativos.", fu: "SEP, Plan de Estudio 2022, ejes articuladores." },
{ id: "c14", a: "curr", f: "d", p: "Un docente de 3.° quiere agregar al programa analítico un contenido sobre el cultivo de fresa, actividad principal de su comunidad. ¿Es posible?", o: ["Sí: el codiseño permite incorporar contenidos locales que respondan al contexto, además de los nacionales", "No: solo pueden trabajarse los contenidos del programa sintético", "Solo si lo autoriza por escrito la SEP"], k: 0,
  e: "El codiseño permite contextualizar los contenidos nacionales e incorporar contenidos regionales o locales pertinentes, decididos por el colectivo docente en el programa analítico, sin dejar de atender los contenidos del programa sintético.", fu: "SEP, Plan de Estudio 2022 (codiseño); Programas Sintéticos, apartado del programa analítico." },
{ id: "c15", a: "curr", f: "d", p: "¿Qué distingue a la interculturalidad crítica, como eje articulador, de la sola convivencia entre culturas?", o: ["Que cuestiona las relaciones de desigualdad y discriminación entre culturas y busca transformarlas", "Que enseña costumbres de otros países", "Que se limita a celebrar festividades tradicionales"], k: 0,
  e: "La interculturalidad crítica no se queda en reconocer la diversidad: analiza las relaciones de poder, desigualdad y discriminación entre grupos culturales y promueve relaciones más justas.", fu: "SEP, Plan de Estudio 2022, ejes articuladores." },
{ id: "c16", a: "curr", f: "or", p: "Ordene las fases de la metodología de Aprendizaje Basado en Problemas según los libros de texto.\n1. Formulemos el problema\n2. Presentemos\n3. Vivamos la experiencia\n4. Recolectemos\n5. Organicemos la experiencia", o: ["2, 4, 1, 5, 3", "1, 2, 3, 4, 5", "2, 1, 4, 3, 5"], k: 0,
  e: "En los libros de proyectos, el ABP sigue: Presentemos, Recolectemos, Formulemos el problema, Organicemos la experiencia, Vivamos la experiencia y Resultados y análisis.", fu: "SEP, Libros de proyectos 2023; Un libro sin recetas para la maestra y el maestro." },
{ id: "c17", a: "curr", f: "d", p: "¿Qué documento de la SEP acompaña a los docentes con orientaciones didácticas, sin dar «recetas», para trabajar con los libros de texto de la NEM?", o: ["Un libro sin recetas, para la maestra y el maestro", "El Manual de procedimientos escolares", "La Guía del CTE de la fase intensiva"], k: 0,
  e: "«Un libro sin recetas, para la maestra y el maestro» (Fases 3, 4, 5 y 6) ofrece orientaciones sobre metodologías y el uso de los libros, reconociendo la autonomía profesional. Aparece en la bibliografía de las guías de USICAMM.", fu: "SEP, Un libro sin recetas para la maestra y el maestro; Bibliografía de las guías USICAMM 2026-2027." },
{ id: "c18", a: "curr", f: "d", p: "¿Qué se entiende por planeación didáctica en el marco de la NEM?", o: ["Una herramienta flexible del docente que organiza la enseñanza a partir del programa analítico, el contexto y las características del grupo", "Un formato único obligatorio para todo el país", "Un requisito administrativo que se entrega al inicio del ciclo"], k: 0,
  e: "Las orientaciones del CTE 2025-2026 (Tema 1, Planeación didáctica) y el Plan 2022 conciben la planeación como herramienta del docente, flexible y situada, derivada del programa analítico; no existe un formato único.", fu: "SEP, Planeación didáctica, CTE 2025-2026, Tema 1; Plan de Estudio 2022." },

/* ===================== INCLUSIÓN, CONVIVENCIA Y PROTECCIÓN ===================== */
{ id: "i01", a: "incl", f: "d", p: "¿Qué son los ajustes razonables?", o: ["Modificaciones y adaptaciones necesarias y adecuadas, que no impongan una carga desproporcionada, para que una persona ejerza su derecho a la educación en igualdad de condiciones", "Reducciones de contenido para los alumnos con bajo rendimiento", "Cambios de grupo para alumnos con discapacidad"], k: 0,
  e: "El concepto proviene de la Convención sobre los Derechos de las Personas con Discapacidad y lo recogen la Constitución (art. 3o, fracción II, inciso f) y la LGE. Son apoyos específicos para eliminar barreras, no la reducción de expectativas.", fu: "CPEUM, art. 3o, fracc. II, inciso f); LGE, arts. 61 a 68 (educación inclusiva)." },
{ id: "i02", a: "incl", f: "r", p: "Relacione cada tipo de barrera para el aprendizaje y la participación con un ejemplo.\n1. Actitudinal\n2. Pedagógica\n3. Organizativa\na) Horarios y agrupamientos que impiden que un alumno reciba apoyo\nb) Bajas expectativas del docente hacia un alumno con discapacidad\nc) Enseñar solo con exposición oral a un grupo diverso", o: ["1b, 2c, 3a", "1a, 2b, 3c", "1c, 2a, 3b"], k: 0,
  e: "Las barreras se ubican en el contexto, no en el alumno: actitudinales (prejuicios, bajas expectativas), pedagógicas (prácticas de enseñanza que no consideran la diversidad) y organizativas (normas, horarios, agrupamientos), entre otras como las físicas.", fu: "LGE, arts. 7 y 16; SEP, Estrategia Nacional de Educación Inclusiva." },
{ id: "i03", a: "incl", f: "d", p: "Un alumno con discapacidad auditiva se integra al grupo. ¿Qué acción del docente es coherente con la educación inclusiva?", o: ["Diseñar desde el inicio actividades con apoyos visuales y varias formas de participar, y coordinarse con USAER y la familia", "Esperar a que tenga un diagnóstico para empezar a trabajar con él", "Sentarlo aparte para que no se distraiga y darle trabajos distintos"], k: 0,
  e: "La inclusión implica eliminar barreras y planear considerando la diversidad desde el inicio (como propone el Diseño Universal para el Aprendizaje), en colaboración con el personal de apoyo y la familia. El diagnóstico no condiciona el derecho a aprender.", fu: "LGE, arts. 61 a 64; Plan de Estudio 2022, eje inclusión." },
{ id: "i04", a: "incl", f: "d", p: "¿Cuáles son los tres principios del Diseño Universal para el Aprendizaje (DUA)?", o: ["Proporcionar múltiples formas de implicación, de representación, y de acción y expresión", "Diagnosticar, canalizar y dar seguimiento", "Observar, registrar y calificar"], k: 0,
  e: "El DUA propone diseñar la enseñanza para todos desde el inicio, ofreciendo múltiples formas de implicación (el porqué), de representación (el qué) y de acción y expresión (el cómo del aprendizaje).", fu: "CAST, Pautas del Diseño Universal para el Aprendizaje; Estrategia Nacional de Educación Inclusiva." },
{ id: "i05", a: "incl", f: "d", p: "Una alumna cuenta a su maestra que un adulto de la escuela la toca de forma inapropiada. ¿Cuál es la primera actuación correcta?", o: ["Escucharla sin juzgar ni interrogar, protegerla, informar de inmediato a la autoridad escolar y seguir el protocolo para dar vista a las autoridades competentes", "Confrontar al adulto señalado para escuchar su versión", "Pedirle a la alumna que lo escriba y lo firme antes de actuar"], k: 0,
  e: "Los lineamientos para prevenir y atender la violencia sexual en educación básica (Acuerdo 17/05/25) y los protocolos de la entidad indican escuchar sin revictimizar, proteger a la niña o niño, informar de inmediato y dar vista a las autoridades. La escuela no investiga ni confronta.", fu: "SEP, Acuerdo 17/05/25; LGDNNA, arts. 46 y 47." },
{ id: "i06", a: "incl", f: "d", p: "¿Qué caracteriza al acoso escolar y lo distingue de un conflicto ocasional entre alumnos?", o: ["Es una agresión intencional, repetida en el tiempo y con desequilibrio de poder entre quien agrede y quien la recibe", "Es cualquier discusión entre alumnos durante el recreo", "Es un conflicto que ocurre fuera de la escuela"], k: 0,
  e: "El acoso escolar se reconoce por la intencionalidad, la repetición y el desequilibrio de poder. Un conflicto puntual entre pares se atiende con mediación y diálogo; el acoso requiere activar el protocolo de la escuela.", fu: "SEP, Acuerdo 14/12/23 (protocolo para erradicar el acoso escolar); Todas y todos contra el acoso escolar. Guía para docentes (2024)." },
{ id: "i07", a: "incl", f: "d", p: "Desde la cultura de paz, ¿cómo conviene atender un conflicto entre dos alumnos por un balón?", o: ["Con diálogo: que cada uno exprese lo que pasó y sintió, y que juntos busquen un acuerdo reparador", "Suspendiendo el uso del balón para todo el grupo", "Con un reporte por escrito a sus familias para que los castiguen"], k: 0,
  e: "La cultura de paz concibe el conflicto como oportunidad de aprendizaje: se privilegian el diálogo, la escucha, la mediación y la reparación del daño sobre el castigo.", fu: "LGE, art. 15, fracc. V; SEP, Promover la cultura de paz en y desde nuestra escuela (2022); Resolución de conflictos en los centros escolares." },
{ id: "i08", a: "incl", f: "d", p: "¿Qué establecen los lineamientos sobre alimentos y bebidas en las escuelas publicados en 2024?", o: ["Que dentro de las escuelas no se preparen, distribuyan ni vendan alimentos y bebidas ultraprocesados con sellos de advertencia, y se promueva la alimentación saludable y el agua simple", "Que solo se prohíben los refrescos en el horario de recreo", "Que cada escuela decide libremente qué productos vende"], k: 0,
  e: "El Acuerdo publicado en el DOF el 30 de septiembre de 2024 establece los lineamientos para la preparación, distribución y expendio de alimentos y bebidas en las escuelas del Sistema Educativo Nacional, en el marco de la estrategia «Vive saludable, vive feliz».", fu: "DOF (30-09-2024), Lineamientos generales sobre alimentos y bebidas en las escuelas; LGE, art. 75." },
{ id: "i09", a: "incl", f: "c", p: "El eje articulador «________» busca que los estudiantes reconozcan las desigualdades entre mujeres y hombres y promuevan relaciones de respeto y equidad.", o: ["Igualdad de género", "Interculturalidad crítica", "Inclusión"], k: 0,
  e: "La igualdad de género es uno de los siete ejes articuladores del Plan 2022 y se vincula con la perspectiva de género que el artículo 3o exige a planes y programas.", fu: "SEP, Plan de Estudio 2022; CPEUM, art. 3o, párrafo duodécimo." },
{ id: "i10", a: "incl", f: "d", p: "¿Qué función tiene la USAER en las escuelas de educación básica?", o: ["Apoyar a la escuela para eliminar barreras para el aprendizaje y la participación de los alumnos, en corresponsabilidad con docentes y familias", "Atender por separado a los alumnos con bajo rendimiento", "Diagnosticar médicamente a los alumnos con discapacidad"], k: 0,
  e: "La Unidad de Servicios de Apoyo a la Educación Regular trabaja con el colectivo docente y las familias para identificar y eliminar barreras. El docente de grupo sigue siendo responsable del aprendizaje de todos sus alumnos.", fu: "LGE, educación especial e inclusiva (arts. 61 a 68); Estrategia Nacional de Educación Inclusiva." },

/* ===================== GESTIÓN ESCOLAR Y MEJORA CONTINUA ===================== */
{ id: "g01", a: "gest", f: "d", p: "¿Qué es el Consejo Técnico Escolar?", o: ["El órgano colegiado de la escuela, integrado por el director y el personal docente, que toma decisiones pedagógicas para la mejora continua y funciona como comunidad de aprendizaje", "Una reunión informativa mensual convocada por la supervisión", "El comité de madres y padres que administra recursos"], k: 0,
  e: "El CTE es el órgano colegiado encargado de tomar y ejecutar decisiones para que la escuela cumpla su misión; sus lineamientos vigentes están en el Acuerdo 05/04/24, y la SEP lo concibe como una comunidad de aprendizaje.", fu: "SEP, Acuerdo 05/04/24 (lineamientos de los CTE); El Consejo Técnico Escolar como Comunidad de Aprendizaje (2025)." },
{ id: "g02", a: "gest", f: "d", p: "¿Cuál es la función del Programa de Mejora Continua (PMC) de la escuela?", o: ["Ser la herramienta de planeación del colectivo para diagnosticar, priorizar, establecer objetivos, metas y acciones, y darles seguimiento", "Ser el informe que se envía a la supervisión al final del ciclo", "Ser el registro de calificaciones del plantel"], k: 0,
  e: "El PMC es la expresión de la planeación de la escuela: parte de un diagnóstico integral, define prioridades, objetivos, metas y acciones, y se le da seguimiento y evaluación en las sesiones del CTE.", fu: "SEP, El proceso de mejora continua: orientaciones para las escuelas de educación básica (2024)." },
{ id: "g03", a: "gest", f: "or", p: "Ordene los momentos del ciclo de reflexión-acción para acompañar a un docente.\n1. Integración de la propuesta\n2. Evaluación\n3. Construcción de la planeación\n4. Puesta en marcha", o: ["3, 1, 4, 2", "1, 3, 2, 4", "4, 3, 1, 2"], k: 0,
  e: "Es el ejemplo de ordenamiento de la guía oficial: el ciclo inicia con la construcción de la planeación, sigue con la integración de la propuesta y su puesta en marcha, y cierra con la evaluación, que alimenta un nuevo ciclo.", fu: "USICAMM, Guía de apoyo 2026-2027; Directores que Hacen Escuela (2015), Acompañar a los docentes: un ciclo de reflexión-acción." },
{ id: "g04", a: "gest", f: "d", p: "Tras un accidente, el director deja pendiente un trámite urgente para atender primero la salud del alumno. ¿Qué principio fundamenta su decisión?", o: ["El derecho de niñas, niños y adolescentes a la protección y el auxilio prioritario en cualquier circunstancia", "La autonomía de gestión del director", "El reglamento interno de la escuela"], k: 0,
  e: "Es el ejemplo de cuestionamiento directo de las guías oficiales. La LGDNNA reconoce el derecho de prioridad: recibir protección y socorro antes que cualquier otro trámite, en cualquier circunstancia.", fu: "USICAMM, Guía de apoyo 2026-2027; LGDNNA, art. 17 (derecho de prioridad)." },
{ id: "g05", a: "gest", f: "d", p: "¿Qué caracteriza a una visita al aula con enfoque formativo?", o: ["Tiene un propósito acordado, se observa con base en criterios conocidos por el docente y concluye con una retroalimentación dialogada que lleva a acuerdos", "Se realiza sin aviso para detectar errores", "Se limita a revisar la planeación y el libro de firmas"], k: 0,
  e: "Las «Visitas al aula» (CPEIP) y los textos de acompañamiento de la bibliografía oficial plantean la observación como herramienta de mejora: propósito claro, criterios compartidos, registro objetivo y retroalimentación que genera acuerdos y seguimiento.", fu: "Ministerio de Educación de Chile, Visitas al aula; Calvo (2018), Diferentes niveles del acompañamiento pedagógico.", per: ["dir", "sup", "atp"] },
{ id: "g06", a: "gest", f: "d", p: "¿Qué significa liderazgo pedagógico (o para el aprendizaje) en la función directiva?", o: ["Que el director centra su gestión en mejorar la enseñanza y el aprendizaje, acompañando a los docentes y promoviendo el trabajo colaborativo", "Que el director imparte clases cuando falta un docente", "Que el director concentra todas las decisiones de la escuela"], k: 0,
  e: "Autores de la bibliografía oficial (Bolívar y Murillo; UNESCO 2025, «Liderar por el aprendizaje») coinciden en que el liderazgo con mayor efecto en el aprendizaje es el centrado en lo pedagógico y distribuido entre el colectivo.", fu: "Bolívar y Murillo (2017), El efecto escuela; UNESCO (2025), Liderazgo en la educación.", per: ["dir", "sup", "atp"] },
{ id: "g07", a: "gest", f: "d", p: "¿Qué papel tiene la supervisión escolar en el Consejo Técnico de Zona y en la mejora de las escuelas?", o: ["Articular entre las escuelas y el sistema educativo, acompañar la mejora continua y fomentar la autonomía profesional de los colectivos", "Fiscalizar el cumplimiento de formatos y sancionar a las escuelas", "Elaborar el programa de mejora de cada escuela"], k: 0,
  e: "La guía de promoción a supervisión describe a la supervisión como instancia articuladora entre escuelas y sistema, que usa el PMC para diagnóstico y seguimiento y participa en los CTE para fomentar la autonomía y la convivencia pacífica.", fu: "USICAMM, Guía de apoyo para supervisión 2026-2027, Área 2; Zorrilla (2013), ¿Transformar la supervisión escolar?", per: ["sup", "dir", "atp"] },
{ id: "g08", a: "gest", f: "c", p: "Una comunidad de aprendizaje se caracteriza porque el colectivo ________ su práctica, comparte experiencias y toma decisiones conjuntas para mejorar el aprendizaje.", o: ["reflexiona sobre", "reporta", "uniforma"], k: 0,
  e: "Molina Ruiz (2005) y la propuesta del CTE como comunidad de aprendizaje plantean que el colectivo aprende de su propia práctica mediante la reflexión, el diálogo y la colaboración.", fu: "Molina Ruiz (2005), Creación y desarrollo de comunidades de aprendizaje; SEP (2025), El CTE como Comunidad de Aprendizaje." },
{ id: "g09", a: "gest", f: "d", p: "¿Qué propone la asesoría técnica pedagógica desde un enfoque colaborativo?", o: ["Acompañar al docente en la reflexión sobre su práctica, construyendo juntos propuestas de mejora a partir de sus necesidades", "Dictar al docente cómo debe dar sus clases", "Revisar y calificar planeaciones"], k: 0,
  e: "Imbernón (2007) y Ventura (2008, «Asesorar es acompañar») plantean al asesor como colaborador que acompaña procesos de reflexión y mejora, no como inspector ni experto que prescribe.", fu: "Imbernón (2007), Asesorar o dirigir; Ventura (2008), Asesorar es acompañar.", per: ["atp", "sup", "dir"] },

/* ===================== ESCUELA, FAMILIAS Y COMUNIDAD ===================== */
{ id: "f01", a: "com", f: "d", p: "¿Qué estrategia fortalece la relación escuela-familias desde la perspectiva de la NEM?", o: ["Abrir espacios de diálogo y participación en los que las familias aporten sus saberes y colaboren en proyectos comunitarios", "Limitar el contacto con las familias a la entrega de boletas", "Pedir a las familias que se encarguen de las tareas que no se terminan en clase"], k: 0,
  e: "Paoli Bolio (2021) y Montaño (2025) proponen relaciones de diálogo y colaboración, reconociendo los saberes de las familias. La NEM concibe a la escuela como centro comunitario.", fu: "Paoli Bolio (2021), Construyendo equidad; Montaño Sánchez (2025), Apuntes sobre las relaciones entre escuela, familias y comunidad." },
{ id: "f02", a: "com", f: "d", p: "Según Bolívar (2006), ¿por qué familia y escuela están «llamados a trabajar en común»?", o: ["Porque la educación de niñas y niños es una responsabilidad compartida y su colaboración mejora los aprendizajes", "Porque la familia debe supervisar el trabajo del docente", "Porque la escuela debe sustituir a la familia en la crianza"], k: 0,
  e: "El texto de Bolívar, incluido en la bibliografía oficial, plantea la corresponsabilidad: la escuela sola no puede, y la colaboración con las familias es un factor de mejora y de equidad.", fu: "Bolívar, A. (2006), Familia y escuela: dos mundos llamados a trabajar en común." },
{ id: "f03", a: "com", f: "d", p: "¿Qué implica concebir a la escuela como «centro de la comunidad» en la NEM?", o: ["Que la escuela se abre a su entorno, retoma problemas y saberes locales y colabora con la comunidad para transformarla", "Que la escuela organiza las fiestas del pueblo", "Que la comunidad decide los contenidos de cada grado"], k: 0,
  e: "La LGE (art. 14) concibe a la escuela como centro de aprendizaje comunitario, y el Plan 2022 coloca a la comunidad como núcleo integrador. Bellido Cala (2021) analiza la apertura de la escuela al entorno como asunto de justicia social.", fu: "LGE, art. 14; Plan de Estudio 2022; Bellido Cala (2021)." },
{ id: "f04", a: "com", f: "d", p: "Ante un caso de un alumno con signos de desnutrición, ¿con quién debe vincularse la escuela además de la familia?", o: ["Con instituciones de salud y de protección (centro de salud, DIF, Procuraduría de Protección), canalizando según el protocolo", "Con nadie: es un asunto privado de la familia", "Solo con la supervisión escolar"], k: 0,
  e: "La guía de supervisión (Área 3.2) señala la gestión con otras instituciones para entornos seguros y saludables, y la prevención, atención y canalización de riesgos a la salud, bajo el principio de protección de la niñez.", fu: "USICAMM, Guía de apoyo 2026-2027, Área 3; LGDNNA, arts. 50 y 57." },

/* ===================== DESARROLLO Y APRENDIZAJE ===================== */
{ id: "a01", a: "apr", f: "d", p: "Según Vygotsky, ¿qué es la zona de desarrollo próximo?", o: ["La distancia entre lo que el niño hace solo y lo que puede lograr con la ayuda de un adulto o un compañero más capaz", "La etapa de desarrollo que corresponde a su edad", "El espacio del aula destinado a actividades individuales"], k: 0,
  e: "Para Vygotsky, la enseñanza eficaz se ubica en la zona de desarrollo próximo: lo que el estudiante aún no hace solo pero sí con apoyo. Bodrova y Leong lo desarrollan en «Herramientas de la mente», de la bibliografía oficial.", fu: "Bodrova y Leong (2004), Herramientas de la mente; Meece (2000)." },
{ id: "a02", a: "apr", f: "c", p: "El concepto de ________, asociado a Bruner, se refiere al apoyo temporal que el docente ofrece y retira gradualmente conforme el estudiante gana autonomía.", o: ["andamiaje", "condicionamiento", "maduración"], k: 0,
  e: "El andamiaje (Wood, Bruner y Ross) describe la ayuda ajustada que se retira poco a poco. Se relaciona con la zona de desarrollo próximo de Vygotsky.", fu: "Meece (2000), Desarrollo del niño y del adolescente; Bodrova y Leong (2004)." },
{ id: "a03", a: "apr", f: "r", p: "Relacione cada etapa del desarrollo cognoscitivo de Piaget con su edad aproximada.\n1. Preoperacional\n2. Operaciones concretas\n3. Operaciones formales\na) De los 11 o 12 años en adelante\nb) De los 2 a los 7 años\nc) De los 7 a los 11 años", o: ["1b, 2c, 3a", "1c, 2b, 3a", "1a, 2c, 3b"], k: 0,
  e: "Piaget propone las etapas sensoriomotora (0-2), preoperacional (2-7), de operaciones concretas (7-11) y de operaciones formales (11-12 en adelante). Las edades son aproximadas.", fu: "Meece (2000), Desarrollo del niño y del adolescente. Compendio para educadores." },
{ id: "a04", a: "apr", f: "d", p: "De acuerdo con «La naturaleza del aprendizaje» (OCDE), ¿qué papel tienen las emociones en el aprendizaje?", o: ["Son parte integral del aprendizaje: la motivación y las emociones influyen en cómo y cuánto se aprende", "No tienen relación con el aprendizaje académico", "Solo importan en preescolar"], k: 0,
  e: "Entre los principios del aprendizaje que propone la OCDE están: el estudiante al centro, la naturaleza social del aprendizaje, las emociones como parte integral, la atención a las diferencias individuales, el desafío sin sobrecarga, la evaluación formativa y las conexiones horizontales.", fu: "OCDE (2010), La naturaleza del aprendizaje: usando la investigación para inspirar la práctica." },
{ id: "a05", a: "apr", f: "d", p: "Un alumno de 2.° de secundaria comienza a razonar hipótesis y a cuestionar normas. ¿Cómo lo explica Meece desde el desarrollo?", o: ["Por el avance hacia el pensamiento formal, que le permite razonar sobre lo posible y lo abstracto", "Por un problema de conducta que debe sancionarse", "Por la influencia de los medios de comunicación únicamente"], k: 0,
  e: "Meece describe que en la adolescencia aparece el pensamiento formal: razonar con hipótesis, pensar en lo abstracto y reflexionar sobre normas y valores. Es una oportunidad para el pensamiento crítico.", fu: "Meece (2000), Desarrollo del niño y del adolescente." },
{ id: "a06", a: "apr", f: "d", p: "¿Qué característica de la planeación didáctica destacan Monetti y Molina (2024)?", o: ["Que es una hipótesis de trabajo que el docente ajusta a partir de lo que sucede en el aula", "Que debe seguirse al pie de la letra para cumplir el programa", "Que la elabora el director para todo el colectivo"], k: 0,
  e: "Monetti y Molina, en la bibliografía oficial, conciben la planificación como anticipación flexible: una hipótesis que se revisa con la realidad del grupo, en sintonía con la autonomía profesional del Plan 2022.", fu: "Monetti y Molina (2024), La planificación didáctica y su enseñanza en la formación docente." },
/* ===================== REACTIVOS AL ESTILO DE LOS EJEMPLOS OFICIALES DE LAS GUÍAS USICAMM 2025-2027 =====================
   Base con situación de aula o de escuela; completamiento con puntos suspensivos; ordenamiento con elementos numerados y
   opciones como secuencias («3, 1, 2, 4»); relación de elementos con una opción de sobra en la segunda columna. */
{ id: "s01", a: "curr", f: "or", p: "La maestra Lucía trabajará un proyecto comunitario en el campo Lenguajes. Ordene los momentos de la fase de planeación y el primero de la fase de acción.\n1. Recuperación\n2. Acercamiento\n3. Identificación\n4. Planificación", o: ["3, 1, 4, 2", "1, 3, 4, 2", "3, 4, 1, 2"], k: 0,
  e: "En la metodología de proyectos comunitarios, la fase de planeación inicia con la identificación de la situación o problema, sigue la recuperación de saberes y termina con la planificación de las producciones. La fase de acción empieza con el acercamiento. Las otras secuencias planifican antes de identificar el problema o de recuperar lo que el grupo ya sabe.", fu: "SEP (2024). Un libro sin recetas, para la maestra y el maestro; programas sintéticos 2022, campo Lenguajes." },
{ id: "s02", a: "curr", f: "or", p: "Un docente de 5.o grado aplicará el aprendizaje basado en indagación con enfoque STEAM. Ordene sus fases.\n1. Organizar y estructurar las respuestas a las preguntas específicas de indagación\n2. Introducción al tema, uso de conocimientos previos y planteamiento del problema\n3. Presentación de los resultados de la indagación y aplicación\n4. Diseño de la investigación y desarrollo de la indagación\n5. Metacognición", o: ["2, 4, 1, 3, 5", "2, 1, 4, 3, 5", "4, 2, 1, 5, 3"], k: 0,
  e: "La indagación STEAM parte de introducir el tema y plantear el problema, luego se diseña y desarrolla la investigación, se organizan las respuestas, se presentan los resultados y cierra con la metacognición, donde el alumnado reflexiona sobre cómo aprendió. Las otras secuencias organizan respuestas antes de investigar o dejan la reflexión antes de presentar resultados.", fu: "SEP (2024). Un libro sin recetas, para la maestra y el maestro; campo Saberes y pensamiento científico." },
{ id: "s03", a: "curr", f: "or", p: "Para un proyecto del campo Ética, naturaleza y sociedades, un maestro usará el aprendizaje basado en problemas. Ordene los momentos.\n1. Formulemos el problema\n2. Presentemos\n3. Vivamos la experiencia\n4. Recolectemos\n5. Organicemos la experiencia\n6. Resultados y análisis", o: ["2, 4, 1, 5, 3, 6", "2, 1, 4, 5, 3, 6", "4, 2, 1, 3, 5, 6"], k: 0,
  e: "El ABP inicia con «Presentemos» (se plantea la situación), sigue «Recolectemos» (saberes previos), «Formulemos el problema», «Organicemos la experiencia», «Vivamos la experiencia» y cierra con «Resultados y análisis». No se formula el problema antes de recuperar lo que el grupo sabe, ni se vive la experiencia sin organizarla antes.", fu: "SEP (2024). Un libro sin recetas, para la maestra y el maestro; campo Ética, naturaleza y sociedades." },
{ id: "s04", a: "curr", f: "or", p: "Una maestra de 3.er grado desarrollará un proyecto de aprendizaje servicio en el campo De lo humano y lo comunitario. Ordene sus etapas.\n1. Organicemos las actividades\n2. Punto de partida\n3. Compartimos y evaluamos lo aprendido\n4. Lo que sé y lo que quiero saber\n5. Creatividad en marcha", o: ["2, 4, 1, 5, 3", "4, 2, 1, 5, 3", "2, 1, 4, 3, 5"], k: 0,
  e: "El aprendizaje servicio parte de un punto de partida (necesidad de la comunidad), sigue con lo que el grupo sabe y quiere saber, la organización de actividades, la puesta en marcha del servicio y cierra compartiendo y evaluando lo aprendido.", fu: "SEP (2024). Un libro sin recetas, para la maestra y el maestro; campo De lo humano y lo comunitario." },
{ id: "s05", a: "curr", f: "r", p: "En una sesión de CTE, el colectivo revisa qué metodología sugieren los programas sintéticos para cada campo formativo. Seleccione la opción que relacione correctamente.\nCampo formativo\n1. Lenguajes\n2. Saberes y pensamiento científico\n3. Ética, naturaleza y sociedades\n4. De lo humano y lo comunitario\nMetodología\na) Aprendizaje basado en problemas\nb) Aprendizaje servicio\nc) Proyectos comunitarios\nd) Indagación con enfoque STEAM\ne) Rincones de aprendizaje", o: ["1c, 2d, 3a, 4b", "1c, 2a, 3d, 4e", "1e, 2d, 3b, 4a"], k: 0,
  e: "Los programas sintéticos sugieren proyectos comunitarios para Lenguajes, indagación STEAM para Saberes y pensamiento científico, ABP para Ética, naturaleza y sociedades y aprendizaje servicio para De lo humano y lo comunitario. Son sugerencias: el colectivo puede usar otras estrategias con su autonomía profesional. Los rincones son una estrategia, no la metodología sugerida de un campo.", fu: "SEP (2022). Plan de Estudio para la educación preescolar, primaria y secundaria; SEP (2024). Un libro sin recetas." },
{ id: "s06", a: "curr", f: "c", p: "Al construir el programa analítico, el colectivo docente de una primaria multigrado decide incorporar contenidos sobre el cultivo de fresa y el trabajo jornalero de las familias que no aparecen en el programa sintético. Esta decisión corresponde al tercer plano, el codiseño, porque…", o: ["…incorpora contenidos locales que responden a la realidad de la comunidad, sin dejar de lado los contenidos nacionales.", "…sustituye los contenidos del programa sintético por los que el colectivo considera más útiles.", "…se limita a ordenar los contenidos nacionales según el calendario agrícola."], k: 0,
  e: "El codiseño permite al colectivo agregar contenidos locales o regionales pertinentes a su contexto, como complemento de los contenidos nacionales, que no se eliminan. Reordenar o dosificar contenidos corresponde a la contextualización (segundo plano).", fu: "SEP (2022). Plan de Estudio, apartado del programa analítico; SEP (2024). Un libro sin recetas." },
{ id: "s07", a: "curr", f: "or", p: "Ordene los tres planos que sigue el colectivo docente para elaborar el programa analítico.\n1. Contextualización de los contenidos del programa sintético\n2. Codiseño de contenidos locales\n3. Lectura de la realidad: análisis del contexto socioeducativo de la escuela", o: ["3, 1, 2", "1, 3, 2", "3, 2, 1"], k: 0,
  e: "Primero se analiza el contexto socioeducativo (lectura de la realidad), después se contextualizan los contenidos nacionales a esa realidad y, por último, se codiseñan contenidos locales cuando hace falta.", fu: "SEP (2022). Plan de Estudio; documentos de orientación del programa analítico para el CTE." },
{ id: "s08", a: "curr", f: "d", p: "Durante la sesión, un alumno de 4.o grado se equivoca al calcular fracciones equivalentes. La maestra le pide que explique cómo lo resolvió, le muestra otro caso con material concreto y le propone volver a intentarlo. ¿Qué rasgo de la evaluación formativa se observa?", o: ["Usa el error como oportunidad para que el alumno reflexione y mejore su proceso de aprendizaje", "Registra el error para justificar la calificación del trimestre", "Evita señalar el error para no afectar la autoestima del alumno"], k: 0,
  e: "En la NEM la evaluación formativa acompaña el proceso: se recupera el error, se dialoga y se da otra oportunidad con apoyos. Registrar solo para calificar es una mirada sumativa; ocultar el error impide aprender de él.", fu: "SEP (2022). Plan de Estudio, apartado de evaluación formativa; SEP (2024). Un libro sin recetas." },
{ id: "s09", a: "curr", f: "d", p: "¿Cuál de las siguientes opciones es un eje articulador del Plan de Estudio 2022?", o: ["Apropiación de las culturas a través de la lectura y la escritura", "Competencias para la vida y el trabajo", "Educación socioemocional y tutoría"], k: 0,
  e: "Los siete ejes articuladores son: inclusión, pensamiento crítico, interculturalidad crítica, igualdad de género, vida saludable, apropiación de las culturas a través de la lectura y la escritura, y artes y experiencias estéticas. Las otras opciones provienen de planes anteriores.", fu: "SEP (2022). Plan de Estudio para la educación preescolar, primaria y secundaria, apartado de ejes articuladores." },
{ id: "s10", a: "curr", f: "r", p: "Relacione cada fase del Plan de Estudio 2022 con los grados que comprende.\nFase\n1. Fase 2\n2. Fase 4\n3. Fase 6\nGrados\na) Primero a tercero de secundaria\nb) Tercero y cuarto de primaria\nc) Primero a tercero de preescolar\nd) Primero y segundo de primaria", o: ["1c, 2b, 3a", "1d, 2b, 3a", "1c, 2a, 3b"], k: 0,
  e: "Fase 1: educación inicial; Fase 2: preescolar; Fase 3: 1.o y 2.o de primaria; Fase 4: 3.o y 4.o; Fase 5: 5.o y 6.o; Fase 6: secundaria.", fu: "SEP (2022). Plan de Estudio, organización por fases." },
{ id: "s11", a: "incl", f: "d", p: "En una escuela de San Quintín se inscribe una niña hablante de mixteco que comprende poco español. ¿Qué acción de la maestra es congruente con el criterio intercultural y con el derecho a la educación en la lengua materna?", o: ["Integrar la lengua y los saberes de la niña en las actividades, apoyarse en la familia y pedir orientación a educación indígena", "Pedir a la familia que en casa hable solo español para que la niña avance más rápido", "Ubicarla en un grado inferior mientras aprende español"], k: 0,
  e: "La Constitución y la LGE reconocen el derecho de los pueblos indígenas a recibir educación en su lengua y con respeto a su cultura. Valorar la lengua materna favorece el aprendizaje; pedir que se abandone o bajar de grado discrimina.", fu: "CPEUM, arts. 2o y 3o, fracción II, inciso g); LGE, capítulo VI De la educación indígena." },
{ id: "s12", a: "incl", f: "d", p: "Una familia jornalera que llegó de Oaxaca quiere inscribir a su hijo a mitad del ciclo, pero no trae acta de nacimiento ni boleta. ¿Qué debe hacer la directora?", o: ["Inscribirlo y orientar a la familia para regularizar los documentos después, sin condicionar el acceso", "Negar la inscripción hasta que presenten todos los documentos", "Aceptarlo como oyente sin registrarlo en el sistema de control escolar"], k: 0,
  e: "El derecho a la educación y el interés superior de la niñez obligan a garantizar el acceso. La falta de documentos no es motivo para negar la inscripción; las normas de control escolar prevén la inscripción y la regularización posterior. Dejarlo como oyente le niega sus derechos de alumno.", fu: "CPEUM, art. 3o; LGE, arts. 5, 7 y 15; normas específicas de control escolar de educación básica." },
{ id: "s13", a: "incl", f: "r", p: "Relacione cada barrera para el aprendizaje y la participación con un ejemplo.\nBarrera\n1. Actitudinal\n2. Pedagógica\n3. De organización\nEjemplo\na) El docente evalúa a todo el grupo con el mismo examen escrito, aunque un alumno tiene discapacidad visual\nb) Algunos compañeros y familias consideran que un alumno con autismo «no debería estar en la escuela»\nc) Los horarios y espacios de la escuela impiden que la maestra de apoyo trabaje con el docente de grupo\nd) El alumno no tiene interés en las actividades", o: ["1b, 2a, 3c", "1a, 2b, 3c", "1b, 2c, 3d"], k: 0,
  e: "Las barreras están en el contexto, no en el alumno: las actitudinales son prejuicios y rechazo; las pedagógicas, la enseñanza y evaluación rígidas; las de organización, la forma en que se dispone el tiempo, el espacio y el personal. El desinterés del alumno no es en sí una barrera del contexto.", fu: "SEP. Estrategia Nacional de Educación Inclusiva; Booth y Ainscow, Índice de inclusión; LGE, capítulo VIII." },
{ id: "s14", a: "incl", f: "c", p: "Los ajustes razonables que la escuela realiza para un alumno con discapacidad son…", o: ["…las modificaciones y adaptaciones necesarias y adecuadas que, sin imponer una carga desproporcionada, garantizan que ejerza su derecho a la educación en igualdad de condiciones.", "…los cambios que el docente hace solo si la familia presenta un diagnóstico médico.", "…la reducción de contenidos para que el alumno no se frustre."], k: 0,
  e: "Los ajustes razonables no dependen de un diagnóstico ni consisten en bajar expectativas: son adecuaciones pertinentes para eliminar barreras y garantizar la participación y el aprendizaje en igualdad de condiciones.", fu: "CPEUM, art. 3o, fracción II, inciso f); LGE, capítulo VIII De la educación inclusiva; Convención sobre los Derechos de las Personas con Discapacidad, art. 2." },
{ id: "s15", a: "incl", f: "or", p: "Un maestro observa que un alumno es agredido de manera repetida por compañeros en el recreo. Ordene las acciones que corresponden.\n1. Informar a la dirección y a las familias involucradas\n2. Detener la agresión y proteger al alumno afectado\n3. Dar seguimiento a los acuerdos y al bienestar de los alumnos\n4. Registrar los hechos de manera objetiva", o: ["2, 4, 1, 3", "4, 2, 1, 3", "1, 2, 4, 3"], k: 0,
  e: "Primero se garantiza la seguridad del alumno, luego se registran los hechos sin juicios, se informa a la autoridad escolar y a las familias y se da seguimiento con medidas formativas. Escribir antes de proteger o avisar antes de detener la agresión deja al alumno expuesto.", fu: "SEP. Protocolos para la prevención, detección y actuación en casos de acoso escolar; LGDNNA, arts. 46 y 57." },
{ id: "s16", a: "incl", f: "or", p: "Durante la jornada se presenta un sismo. Ordene las acciones que el docente realiza con su grupo.\n1. Pasar lista en el punto de reunión\n2. Mantener la calma y replegarse en las zonas de menor riesgo del aula\n3. Evacuar por la ruta establecida cuando termine el movimiento\n4. Reportar a la dirección si falta algún alumno", o: ["2, 3, 1, 4", "3, 2, 1, 4", "2, 1, 3, 4"], k: 0,
  e: "Durante el movimiento no se corre: se mantiene la calma y se repliega en zonas seguras. Al cesar, se evacua por la ruta establecida, se pasa lista en el punto de reunión y se reporta cualquier ausencia.", fu: "SEP. Entornos escolares seguros en escuelas de educación básica; programa interno de protección civil escolar." },
{ id: "s17", a: "incl", f: "d", p: "En la cooperativa de la escuela se venden refrescos y frituras con sellos de advertencia. ¿Qué establecen los lineamientos vigentes para la venta de alimentos en escuelas?", o: ["Prohíben vender en las escuelas alimentos y bebidas con sellos de advertencia y promueven el acceso a agua potable", "Permiten venderlos siempre que la cooperativa lo apruebe en asamblea", "Solo limitan su venta en preescolar"], k: 0,
  e: "Los lineamientos generales para la preparación, distribución y expendio de alimentos y bebidas en las escuelas, publicados el 30 de septiembre de 2024, prohíben los productos con sellos de advertencia en todos los planteles de educación básica y promueven la alimentación saludable y el agua simple.", fu: "Acuerdo por el que se emiten los Lineamientos generales para la preparación, distribución y expendio de alimentos y bebidas, DOF 30/09/2024; LGE, art. 75." },
{ id: "s18", a: "norm", f: "c", p: "De acuerdo con la Ley General de Educación, el Estado priorizará el interés superior de niñas, niños, adolescentes y jóvenes en el ejercicio de su derecho a la educación, por lo que garantizará…", o: ["…el desarrollo de programas y políticas públicas que hagan efectivo este principio constitucional.", "…que cada escuela decida libremente sus criterios de admisión.", "…la aplicación de exámenes de selección para el ingreso a primaria."], k: 0,
  e: "La LGE retoma el principio constitucional y obliga al Estado a desarrollar programas y políticas que lo hagan efectivo. Los criterios de admisión discrecionales o los exámenes de selección en educación básica contradicen el carácter universal e inclusivo.", fu: "LGE, art. 2; CPEUM, art. 3o, párrafo quinto." },
{ id: "s19", a: "norm", f: "d", p: "Un padre de familia exige que la escuela enseñe la doctrina de su religión como parte del programa. ¿Qué respuesta da la directora con base en el artículo 3o?", o: ["La educación que imparte el Estado es laica, por lo que se mantiene ajena a cualquier doctrina religiosa", "Se puede incluir si la mayoría de las familias lo aprueba", "Se puede incluir como actividad obligatoria fuera del horario"], k: 0,
  e: "La fracción I del artículo 3o establece que la educación que imparte el Estado será laica y, por tanto, ajena a cualquier doctrina religiosa. El laicismo garantiza la libertad de creencias de todas las familias; no depende de mayorías.", fu: "CPEUM, arts. 3o, fracción I, y 24." },
{ id: "s20", a: "norm", f: "r", p: "Relacione cada fin de la educación con su descripción, según la Ley General de Educación.\n1. Contribuir al desarrollo integral\n2. Promover el respeto irrestricto de la dignidad humana\n3. Inculcar el enfoque de derechos humanos y de igualdad sustantiva\na) Para el ejercicio pleno y responsable de sus capacidades\nb) Como valor fundamental e inalterable de la persona\nc) Promoviendo el conocimiento, respeto y ejercicio de los derechos de todas las personas\nd) Para aprobar los exámenes de ingreso al siguiente nivel", o: ["1a, 2b, 3c", "1b, 2a, 3c", "1a, 2c, 3d"], k: 0,
  e: "La LGE, en su artículo 15, señala entre los fines de la educación el desarrollo integral para el ejercicio pleno de las capacidades, el respeto a la dignidad humana como valor fundamental e inalterable y el enfoque de derechos humanos e igualdad sustantiva.", fu: "LGE, art. 15." },
{ id: "s21", a: "norm", f: "d", p: "¿Qué obligación tienen madres, padres o tutores según el artículo 31 constitucional?", o: ["Hacer que sus hijas, hijos o pupilos menores de dieciocho años concurran a las escuelas para recibir educación obligatoria", "Participar en todas las sesiones del Consejo Técnico Escolar", "Aportar cuotas para el mantenimiento del plantel"], k: 0,
  e: "El artículo 31, fracción I, establece la obligación de hacer que los menores de dieciocho años concurran a la escuela y de revisar su progreso y desempeño. Las cuotas son voluntarias y nunca condicionan la inscripción; el CTE lo integran el director y los docentes.", fu: "CPEUM, art. 31, fracción I; LGE, arts. 7 y 128." },
{ id: "s22", a: "gest", f: "d", p: "El director de una escuela pide a los docentes que cada sesión de CTE se dedique a llenar formatos administrativos. ¿Qué indican los lineamientos del Consejo Técnico Escolar sobre el propósito de sus sesiones?", o: ["Son espacios de trabajo colegiado para analizar la situación de la escuela, tomar decisiones pedagógicas y dar seguimiento a la mejora", "Son reuniones para atender la carga administrativa del ciclo", "Son espacios de capacitación que dirige la supervisión"], k: 0,
  e: "El CTE es el órgano colegiado de mayor decisión técnico pedagógica de la escuela. Sus sesiones se centran en el aprendizaje del alumnado, el programa analítico y la mejora continua, no en trámites.", fu: "Acuerdo 05/04/24 por el que se emiten los Lineamientos para la organización y funcionamiento de los Consejos Técnicos Escolares." },
{ id: "s23", a: "gest", f: "or", p: "El colectivo de una escuela elabora su Programa Escolar de Mejora Continua. Ordene sus elementos.\n1. Metas\n2. Diagnóstico\n3. Seguimiento y evaluación\n4. Objetivos\n5. Acciones", o: ["2, 4, 1, 5, 3", "4, 2, 1, 5, 3", "2, 1, 4, 3, 5"], k: 0,
  e: "El PEMC parte del diagnóstico de la escuela; de él surgen los objetivos, que se concretan en metas medibles; se definen acciones para alcanzarlas y se establece su seguimiento y evaluación.", fu: "SEP. Orientaciones para elaborar el Programa Escolar de Mejora Continua; LGE, art. 107 (mejora continua)." },
{ id: "s24", a: "gest", f: "d", p: "En la sesión de CTE, el colectivo identifica varias problemáticas: baja comprensión lectora, inasistencias, conflictos en el recreo y falta de agua en los baños. ¿Qué criterio debe orientar la priorización?", o: ["Atender primero las que más afectan el aprendizaje y el bienestar del alumnado y que el colectivo puede transformar", "Atender primero las que la supervisión pidió en su último oficio", "Atender todas al mismo tiempo para no dejar ninguna fuera"], k: 0,
  e: "La mejora continua exige priorizar con base en el diagnóstico, el impacto en el aprendizaje y el bienestar, y la capacidad real de la escuela para incidir; las demás se canalizan o se atienden después. Querer atender todo a la vez dispersa el esfuerzo.", fu: "Lineamientos de los CTE (Acuerdo 05/04/24); orientaciones del PEMC." },
{ id: "s25", a: "gest", f: "d", p: "Una supervisora visita una escuela y observa que un docente usa solo dictado y copia. ¿Qué acción corresponde a su función de asesoría y acompañamiento?", o: ["Dialogar con el docente sobre lo observado, acordar estrategias y dar seguimiento en visitas posteriores", "Levantar un acta administrativa por incumplimiento del Plan de Estudio", "Pedir al director que cambie al docente de grupo"], k: 0,
  e: "La supervisión en la NEM prioriza el acompañamiento pedagógico: observar, retroalimentar con respeto, construir acuerdos y dar seguimiento. Las medidas administrativas no mejoran la práctica por sí mismas.", fu: "LGE, art. 14 y título de la mejora continua; perfiles profesionales de supervisión, USICAMM 2026-2027.", per: ["sup", "dir", "atp"] },
{ id: "s26", a: "gest", f: "c", p: "La asesoría técnica pedagógica tiene como propósito central…", o: ["…acompañar al personal docente y directivo para fortalecer sus prácticas y favorecer el aprendizaje del alumnado.", "…supervisar el cumplimiento de la normatividad administrativa en las escuelas.", "…sustituir al docente frente a grupo cuando se ausenta."], k: 0,
  e: "El ATP brinda asesoría y acompañamiento técnico pedagógico a docentes y directivos para la mejora de sus prácticas; no es una función de control administrativo ni de suplencia.", fu: "Ley General del Sistema para la Carrera de las Maestras y los Maestros; perfil del ATP, USICAMM 2026-2027.", per: ["atp", "sup", "dir"] },
{ id: "s27", a: "com", f: "d", p: "En una comunidad agrícola, muchas familias trabajan en el campo desde temprano y no pueden asistir a reuniones a las 9:00. ¿Qué acción favorece la vinculación escuela-comunidad?", o: ["Acordar con las familias horarios y formas de comunicación accesibles, como reuniones por la tarde o mensajes", "Registrar como «familias desinteresadas» a quienes no asisten", "Suspender las reuniones porque nadie asiste"], k: 0,
  e: "La NEM coloca a la comunidad como núcleo integrador. Reconocer las condiciones de vida de las familias y adaptar la comunicación favorece su participación; etiquetarlas o cancelar el vínculo lo debilita.", fu: "SEP (2022). Plan de Estudio, la escuela y la comunidad; LGE, arts. 128 a 130." },
{ id: "s28", a: "com", f: "d", p: "Un maestro organiza con su grupo una campaña para limpiar el arroyo del poblado con apoyo del delegado y de las familias. ¿Qué planteamiento del Plan de Estudio 2022 se concreta?", o: ["La comunidad como espacio social, cultural y de aprendizaje, en la que la escuela participa para transformar su realidad", "La escuela como espacio separado de la comunidad para proteger al alumnado", "La enseñanza de contenidos ambientales solo dentro del aula"], k: 0,
  e: "El Plan 2022 propone que la escuela se vincule con la comunidad y que el aprendizaje se oriente a comprender y transformar problemas reales del entorno.", fu: "SEP (2022). Plan de Estudio, la comunidad como núcleo integrador de los procesos de enseñanza y aprendizaje." },
{ id: "s29", a: "apr", f: "r", p: "Relacione cada etapa del desarrollo cognoscitivo propuesta por Piaget con su rasgo principal.\nEtapa\n1. Preoperacional\n2. Operaciones concretas\n3. Operaciones formales\nRasgo\na) Razona de manera lógica sobre situaciones concretas y comprende la conservación\nb) Usa símbolos y lenguaje, con pensamiento egocéntrico\nc) Razona de manera hipotética y abstracta\nd) Conoce el mundo mediante los sentidos y la acción", o: ["1b, 2a, 3c", "1d, 2a, 3c", "1b, 2c, 3a"], k: 0,
  e: "En la etapa preoperacional (2 a 7 años aprox.) aparece la función simbólica con pensamiento egocéntrico; en las operaciones concretas (7 a 11) el razonamiento lógico se aplica a lo concreto; en las formales (11 en adelante) se razona de forma hipotética. La exploración sensorial corresponde a la etapa sensoriomotora.", fu: "Meece, J. (2000). Desarrollo del niño y del adolescente. Compendio para educadores. SEP." },
{ id: "s30", a: "apr", f: "c", p: "Según Vygotsky, la zona de desarrollo próximo es la distancia entre…", o: ["…lo que el niño hace solo y lo que logra con la ayuda de un adulto o de un compañero más capaz.", "…la edad cronológica del niño y su edad mental.", "…lo que el niño sabe al iniciar el ciclo y lo que sabe al terminarlo."], k: 0,
  e: "La ZDP es el espacio entre el desempeño independiente y el desempeño asistido. Allí la enseñanza es más eficaz, porque los apoyos se retiran gradualmente conforme el niño gana autonomía.", fu: "Bodrova, E. y Leong, D. (2004). Herramientas de la mente. SEP." },
{ id: "s31", a: "apr", f: "d", p: "En preescolar, una educadora observa que durante el juego de la «tiendita» los niños negocian roles, siguen reglas y usan números para cobrar. ¿Qué planteamiento sustenta el uso del juego?", o: ["El juego es una forma privilegiada de aprender, porque los niños regulan su conducta y usan herramientas culturales en situaciones con sentido", "El juego es un premio para cuando terminan las actividades de aprendizaje", "El juego solo favorece el desarrollo físico"], k: 0,
  e: "Desde la perspectiva vygotskiana y en el programa de Fase 2, el juego de roles favorece la autorregulación, el lenguaje y el pensamiento matemático en situaciones significativas.", fu: "Bodrova y Leong (2004). Herramientas de la mente; SEP (2022). Programa sintético de la Fase 2." },
{ id: "s32", a: "curr", f: "d", p: "Un colectivo de secundaria decide que en un proyecto sobre el agua participen Ciencias, Geografía, Matemáticas y Español. ¿Qué rasgo del Plan de Estudio 2022 se concreta?", o: ["El trabajo integrado de las disciplinas dentro de los campos formativos para abordar problemas de la realidad", "La enseñanza separada de cada asignatura con su propio proyecto", "La sustitución de las disciplinas por un solo maestro"], k: 0,
  e: "El Plan 2022 organiza el currículo en campos formativos que integran disciplinas para comprender situaciones complejas. En secundaria las disciplinas se mantienen, pero se articulan.", fu: "SEP (2022). Plan de Estudio, campos formativos e integración curricular." },
{ id: "s33", a: "curr", f: "c", p: "La autonomía profesional del magisterio en el Plan de Estudio 2022 implica que el docente…", o: ["…tome decisiones sobre cómo enseñar y qué contenidos priorizar a partir del conocimiento de su grupo y su contexto.", "…pueda dejar de lado los programas sintéticos si no coinciden con su experiencia.", "…trabaje sin coordinarse con el colectivo docente."], k: 0,
  e: "La autonomía profesional reconoce al docente como profesional capaz de reinterpretar y contextualizar el currículo, siempre dentro del marco del Plan y del programa analítico construido en colectivo.", fu: "SEP (2022). Plan de Estudio, autonomía profesional del magisterio." },
{ id: "s34", a: "norm", f: "d", p: "Una docente se da cuenta de que una alumna de 6.o grado presenta señales de maltrato en casa. ¿Qué corresponde hacer?", o: ["Informar de inmediato a la dirección para que se dé aviso a la Procuraduría de Protección de Niñas, Niños y Adolescentes y se active el protocolo", "Esperar a reunir más pruebas antes de comentarlo", "Hablar con los padres para pedirles que cambien su conducta"], k: 0,
  e: "La LGDNNA obliga a quienes tienen conocimiento de casos de niñas, niños o adolescentes afectados en sus derechos a hacerlo del conocimiento de las autoridades competentes. La escuela no investiga ni confronta a la familia: protege y canaliza.", fu: "LGDNNA, arts. 12 y 47; protocolos de actuación para la prevención y atención del abuso y maltrato en escuelas de educación básica." },
{ id: "s35", a: "gest", f: "d", p: "La directora observa que el grupo de 2.o grado tiene muchas inasistencias en temporada de cosecha. ¿Qué acción es congruente con el derecho a la permanencia?", o: ["Analizar las causas con las familias y el colectivo y diseñar estrategias de recuperación y seguimiento de los alumnos", "Dar de baja a quienes acumulen faltas para mantener actualizada la estadística", "Esperar a que termine la temporada para retomar el programa"], k: 0,
  e: "La escuela debe identificar a los alumnos en riesgo de abandono y generar estrategias para su permanencia: acuerdos con familias, actividades de recuperación, flexibilidad y seguimiento.", fu: "CPEUM, art. 3o; LGE, arts. 9 y 15; lineamientos de los CTE." }
];
